$catalog$::jsonb;
  v_entry jsonb;
  v_row record;
  v_path jsonb;
  v_path_def jsonb;
  v_paths jsonb;
  v_skills jsonb;
  v_resource_max integer;
  v_attr_one text;
  v_attr_two text;
  v_dtype text;
begin
  for v_entry in select value from jsonb_array_elements(v_catalog)
  loop
    select id, payload into v_row from public.v2_classes where name = v_entry->>'name' limit 1;
    if not found then
      raise exception 'Classe não encontrada: %', v_entry->>'name';
    end if;

    v_resource_max := greatest(1, coalesce((v_row.payload #>> '{resource,maximum}')::integer, 100));
    v_attr_one := v_entry #>> '{attrs,0}';
    v_attr_two := v_entry #>> '{attrs,1}';
    v_dtype := v_entry->>'dtype';
    v_skills := public._v2_rework_skill_list(v_entry->'base', array[1,8,16,24,32,40,48], v_attr_one, v_attr_two, v_dtype, v_resource_max);
    v_paths := '[]'::jsonb;

    for v_path in select value from jsonb_array_elements(coalesce(v_row.payload->'paths','[]'::jsonb))
    loop
      select value into v_path_def
      from jsonb_array_elements(v_entry->'paths')
      where value->>'key' = v_path->>'key'
      limit 1;

      if v_path_def is not null then
        v_path := jsonb_set(
          v_path,
          '{skills}',
          public._v2_rework_skill_list(v_path_def->'skills', array[50,60,70,85,100], v_attr_one, v_attr_two, v_dtype, v_resource_max),
          true
        );
      end if;
      v_paths := v_paths || jsonb_build_array(v_path);
      v_path_def := null;
    end loop;

    update public.v2_classes
    set payload = v_row.payload || jsonb_build_object(
      'description', v_entry->>'description',
      'mechanic', v_entry->'mechanic',
      'passive', v_entry->'passive',
      'progression', v_skills,
      'paths', v_paths
    ), updated_at = now()
    where id = v_row.id;
  end loop;
end;
$$;

drop function public._v2_rework_skill_list(jsonb,integer[],text,text,text,integer);
drop function public._v2_rework_skill(text,integer,text,text,text,text,text,integer);
drop function public._v2_rework_op(text,text,text,jsonb,text,integer,jsonb);
